import {updateTypes,issueStatuses,clientImpacts,authorizations} from './service-issues.mjs';
const cash=n=>new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(n);
export function serviceIssueView(s,safe,repairId,selectedIssue){
 const repair=s.repairOrders.find(r=>r.id===repairId),cases=s.issueCases.filter(i=>i.repairId===repairId),chosen=cases.find(i=>i.id===selectedIssue);
 const current=chosen||{title:'',updateType:'Initial inspection',severity:'Normal',status:'Open',workDone:'',findings:'',nextAction:'',parts:'',impactType:'No service impact',impactNote:'',downtimeMinutes:0,extraCostCAD:0,clientNotified:false,authorization:'Not requested',followupAt:''};
 const options=(values,value)=>values.map(v=>`<option ${v===value?'selected':''}>${safe(v)}</option>`).join('');
 const journal=s.issueHistory.filter(e=>e.repairId===repairId&&(!chosen||e.issueId===chosen.id));
 const open=cases.filter(i=>i.status!=='Resolved'),emergency=open.filter(i=>i.severity==='Emergency');
 return `<section class="card service-issue-workspace"><div class="card-head"><div><h2>Technician work & client impact</h2><p>${safe(repair.client)} · ${safe(repair.product)} · ${repair.id} · ${repair.clientId}</p></div><span class="badge ${emergency.length?'red':'gray'}">${emergency.length?emergency.length+' emergency issue'+(emergency.length===1?'':'s'):open.length?open.length+' active issues':'No active issues'}</span></div><div class="panel-body"><p class="definition">Record diagnosis, work performed, emergency findings, urgent replacements and their effect on this client. Each update becomes a new retained version. Estimates below belong to each issue; they are not summed, charged or approved automatically.</p><div class="client-impact-cards">${cases.map(i=>`<button class="issue-client-card" data-service-issue="${i.id}"><span class="badge ${i.severity==='Emergency'?'red':i.severity==='Urgent'?'amber':'gray'}">${i.severity} · ${i.status}</span><b>${safe(i.title)}</b><small>${i.id} · v${i.version} · ${safe(i.updateType)}</small><p>${safe(i.impactType)}: ${safe(i.impactNote)}</p><small>${i.extraCostCAD?'Proposed additional cost: '+cash(i.extraCostCAD):'No additional cost proposed'} · Approval: ${i.authorization}</small><small>${i.downtimeMinutes?'Estimated downtime: '+i.downtimeMinutes+' minutes':'No downtime estimate recorded'} · Client ${i.clientNotified?'notified (as recorded)':'not yet notified'}</small></button>`).join('')||'<p class="definition">No technician issue updates recorded for this client yet.</p>'}</div><label for="service-issue-select">Document a new issue or update an existing one</label><select id="service-issue-select"><option value="new">New issue / work record</option>${cases.map(i=>`<option value="${i.id}" ${chosen?.id===i.id?'selected':''}>${i.id} · ${safe(i.title)} · v${i.version}</option>`).join('')}</select><form id="service-issue-form" class="issue-form"><div class="issue-form-column"><h3>Technician work record</h3><label for="issue-title">Issue title</label><input id="issue-title" name="title" maxlength="160" value="${safe(current.title)}" ${chosen?'readonly':''} required placeholder="Example: drain pump failure"><label for="issue-type">Issue update type</label><select id="issue-type" name="updateType">${options(updateTypes,current.updateType)}</select><label for="issue-severity">Priority</label><select id="issue-severity" name="severity">${options(['Normal','Urgent','Emergency'],current.severity)}</select><label for="issue-status">Current issue status</label><select id="issue-status" name="status">${options(issueStatuses,current.status)}</select><label for="issue-work">Work performed in this update</label><textarea id="issue-work" name="workDone" required maxlength="1000" placeholder="Describe what you did. If no repair was performed, say so."></textarea><label for="issue-findings">Findings / diagnosis</label><textarea id="issue-findings" name="findings" required maxlength="1000">${safe(current.findings)}</textarea><label for="issue-parts">Parts or replacement required</label><input id="issue-parts" name="parts" maxlength="500" value="${safe(current.parts)}"><label for="issue-next">Next action / follow-up plan</label><textarea id="issue-next" name="nextAction" required maxlength="1000">${safe(current.nextAction)}</textarea></div><div class="issue-form-column"><h3>Ramifications for this client</h3><label for="issue-impact">Primary client impact</label><select id="issue-impact" name="impactType">${options(clientImpacts,current.impactType)}</select><label for="issue-impact-note">Client-impact details</label><textarea id="issue-impact-note" name="impactNote" required maxlength="1000" placeholder="What changes for the client: service, timing, access, safety or proposed cost?">${safe(current.impactNote)}</textarea><label for="issue-downtime">Estimated downtime · minutes</label><input type="number" id="issue-downtime" name="downtimeMinutes" min="0" max="525600" step="1" value="${current.downtimeMinutes}" required><label for="issue-cost">Proposed additional cost · CAD</label><input type="number" id="issue-cost" name="extraCostCAD" min="0" max="1000000" step="0.01" value="${current.extraCostCAD}" required><label for="issue-authorization">Client authorization as recorded</label><select id="issue-authorization" name="authorization">${options(authorizations,current.authorization)}</select><label class="confirmation-check"><input type="checkbox" name="clientNotified" ${current.clientNotified?'checked':''}> Client has been informed of this update</label><label for="issue-followup">Follow-up due · Toronto time</label><input type="datetime-local" id="issue-followup" name="followupAt" value="${current.followupAt}"><div class="callout">Recording an emergency or replacement does not approve work, order parts, charge the client, send a message or move the appointment. Record those decisions explicitly and use the rescheduling form when the visit time changes.</div><button class="btn primary" type="submit">${chosen?'Append technician update':'Create issue with client-impact record'}</button><p class="definition">Recorded as ${safe(s.operatorName)}. Demo identity is self-declared; shared verified-user records remain future work.</p></div></form><h3 class="history-title">Client-linked issue journal · ${journal.length||'No'} recorded updates</h3><ol class="workflow-timeline">${journal.slice().reverse().map(e=>`<li class="workflow-event"><div class="risk-line"><b>${safe(e.issueId)} · v${e.version} · ${safe(e.after.updateType)}</b><span class="badge ${e.after.severity==='Emergency'?'red':e.after.severity==='Urgent'?'amber':'gray'}">${e.after.severity} · ${e.after.status}</span></div><small>${safe(new Date(e.time).toLocaleString('en-US',{timeZone:'UTC'}))} UTC · Recorded by ${safe(e.actor)} · ${e.clientId}</small><p><b>Work:</b> ${safe(e.after.workDone)}</p><p><b>Findings:</b> ${safe(e.after.findings)}</p><p><b>Client impact:</b> ${safe(e.after.impactType)} · ${safe(e.after.impactNote)}</p><p><b>Parts:</b> ${safe(e.after.parts||'None recorded')} · <b>Next action:</b> ${safe(e.after.nextAction)}</p><dl class="step-diff"><div><dt>Issue status</dt><dd>${safe(e.before?.status||'New issue')} → ${e.after.status}</dd></div><div><dt>Proposed cost</dt><dd>${e.before?cash(e.before.extraCostCAD):'No prior estimate'} → ${cash(e.after.extraCostCAD)}</dd></div><div><dt>Client approval</dt><dd>${e.before?.authorization||'No prior record'} → ${e.after.authorization}</dd></div><div><dt>Notification</dt><dd>${e.after.clientNotified?'Client informed as recorded':'Not yet recorded as informed'}</dd></div><div><dt>Downtime</dt><dd>${e.after.downtimeMinutes} minutes estimated</dd></div><div><dt>Follow-up</dt><dd>${safe(e.after.followupAt?e.after.followupAt.replace('T',' · ')+' Toronto':'None scheduled')}</dd></div></dl></li>`).join('')||'<li class="definition">Updates will appear here after recording the first technician report.</li>'}</ol></div></section>`;
}
